mat = {l.split('\t')[0]: list(map(int, l.split('\t')[1:])) for l in lines[1:]}
genes = list(mat)

rep = {r['cell_id']: (r['sample_id'], r['group']) for r in csv.DictReader(open('replicate.tsv'), delimiter='\t')}
pairs = {'P1': ('S1','S3'), 'P2': ('S2','S4')}  # (a=ctrl, b=treat)

# replicate pipeline: per cluster, per sample, sum raw counts over kept genes; lib normalize 1e4; log1p
for target_cluster in (0, 1):
    # per sample: cells in cluster
    cells_of = {}
    for ci, cid in enumerate(header):
        s, g = rep[cid]
        if cl[cid] == target_cluster:
            cells_of.setdefault(s, []).append(ci)
    totals = {s: sum(mat[g][ci] for g in genes for ci in idxs) for s, idxs in cells_of.items()}
    # gene g1
    diffs = []
    for p,(sa,sb) in pairs.items():
        va = math.log1p(sum(mat['g1'][ci] for ci in cells_of[sa]) / totals[sa] * 10000)
        vb = math.log1p(sum(mat['g1'][ci] for ci in cells_of[sb]) / totals[sb] * 10000)
        diffs.append(va - vb)
    n = len(diffs)
    m = sum(diffs)/n
    var = sum((d-m)**2 for d in diffs)/(n-1)
    t = m/math.sqrt(var)*math.sqrt(n)
    print(f"cluster {target_cluster} g1: mean_diff={m!r} t={t!r} (n={n})")
